from flask import Flask, current_app

def create_app(label):
    app = Flask(__name__)
    app.config['TESTING'] = True
    app.config['DEMO_LABEL'] = label

    @app.get('/label')
    def label_view():
        return {'label': current_app.config['DEMO_LABEL']}

    return app

first = create_app('practice')
second = create_app('review')
print(first.test_client().get('/label').json['label'])
print(second.test_client().get('/label').json['label'])

